"""Generate an instruction-timed 2A03 core with NES bus hooks.

Keeps the standalone NMOS core unchanged. CpuRun accepts/returns CYCLES;
the last instruction may overshoot, and the caller carries that debt.
"""
from pathlib import Path
import re
from py65.devices.mpu6502 import MPU
root=Path(__file__).resolve().parent
s=(root/'nmos6502.pico').read_text()
s=s.replace('Left = r11, X = r4, FZ = r5','Left = r11')
s=s.replace('; NMOS 6502 core: the input rp2040/generate_cpu.py turns into the 2A03 core (cpu2a03.pico).',
            '; Generated by rp2040/generate_cpu.py. NES 2A03; CpuRun budgets CPU cycles.')
# D is readable/writable but never enables BCD arithmetic on the 2A03.
s,n=re.subn(r'  If FD\n.*?  Else\n(.*?)\n  EndIf',lambda m:m[1],s,flags=re.S)
assert n==16,n
s=s.replace('Global CpuCycles.i, InitIndex.i','Global CpuCycles.i, InitIndex.i\nGlobal AccessPhase.i, NesStall.i')
s=s.replace('Global AccessPhase.i, NesStall.i','Global AccessPhase.i, NesStall.i, NesRunStart.i')
s=s.replace('''  CompilerIf #CPU_TIMING = 1
    CpuCycles = CpuCycles + c
  CompilerEndIf''','''  CpuCycles = CpuCycles + c
  Left = Left - c''')
s=s.replace('''      CpuCycles = CpuCycles + 1''','''      Charge(1)''')
start=s.index('Macro NextOp(c)')
end=s.index('EndMacro',start)+len('EndMacro')
s=s[:start]+'''Macro NextOp(c)
  Charge(c)
  If NesStall
    Charge(NesStall)
    NesStall = 0
  EndIf
  If Left <= 0
    Goto Done
  EndIf
  DispatchNext()
EndMacro'''+s[end:]
s=s.replace('''      mov r0, r8
      ldr r1, =global_m''','''      mov r0, r8
      ldr r1, =$8000
      cmp r0, r1
      blo __ul_cpurun_slowfetch
      ldr r1, =global_m''')
s=s.replace('Illegal:\n','''SlowFetch:
  Tmp = NesRead(PC)
  PC = (PC + 1) & $FFFF
  Goto Dispatch(Tmp)
Illegal:
''')
s=s.replace('  Budget = n\n','  NesRunStart = CpuCycles\n  Budget = n\n')
s=s.replace('ProcedureReturn Budget - Left','ProcedureReturn CpuCycles - NesRunStart')
s=s.replace('  Charge(c)\n  If NesStall','  Charge(c)\n  NesInstructions = NesInstructions + 1\n  If NesStall')
s=s.replace('Global AccessPhase.i, NesStall.i, NesRunStart.i','Global AccessPhase.i, NesStall.i, NesRunStart.i\nGlobal NesInstructions.i\nGlobal NesOpenBus.i\nGlobal PrgBase.i, PrgBias.i')
# Balanced substitution permits nested addressing expressions.
def calls(text):
    result=''; pos=0
    while (at:=text.find('M(',pos))>=0:
        result+=text[pos:at]; depth=1; end=at+2
        while depth:
            if text[end]=='(': depth+=1
            elif text[end]==')': depth-=1
            end+=1
        result+='NesRead('+calls(text[at+2:end-1])+')'; pos=end
    return result+text[pos:]
lines=[]
for line in s.splitlines():
    if line.startswith('Global Dim M.'):
        lines.append(line); continue
    # Stack and direct instruction fetches use ordinary backing RAM.
    if line.strip()=='M($100 + S) = v' or line.strip()=='v = M($100 + S)':
        lines.append(line); continue
    m=re.match(r'  M\((.*)\) = (.*)$',line)
    if m:
        lines.append(f'  NesWrite({m[1]}, {m[2]})'); continue
    if line.lstrip().startswith('Op') and ': ; $' in line:
        lines.append(line)
        opcode=int(line.split(':')[0][2:],16)
        lines.append(f'  AccessPhase = {MPU.cycletime[opcode]-1}')
        continue
    lines.append(calls(line))
s='\n'.join(lines)+'\n'
# NMOS memory RMW writes the old byte, then the modified byte.
for match in list(re.finditer(r'(Op[0-9A-F]{2}: ; \$[0-9A-F]{2} (?:ASL|LSR|ROL|ROR|INC|DEC) (?!acc).*?)(?=Op[0-9A-F]{2}:|Done:)',s,re.S))[::-1]:
 body=match[0]
 if 'NesWrite(Ea, Res)' in body:
  body=body.replace('  Value = NesRead(Ea)', '  AccessPhase = AccessPhase - 2\n  Value = NesRead(Ea)\n  AccessPhase = AccessPhase + 2')
  body=body.replace('  NesWrite(Ea, Res)','  AccessPhase = AccessPhase - 1\n  NesWrite(Ea, Value)\n  AccessPhase = AccessPhase + 1\n  NesWrite(Ea, Res)')
  s=s[:match.start()]+body+s[match.end():]

# Fast operand helpers own the reserved PC and use no ABI parameters.
s=s.replace('''Macro Fetch(v)
  v = NesRead(PC)
  PC = (PC + 1) & $FFFF
EndMacro''','''Macro Fetch(v)
  v = CpuFetchByte()
EndMacro''')
s=s.replace('''  Ea = NesRead(PC) | (NesRead((PC + 1) & $FFFF) << 8)
  PC = (PC + 2) & $FFFF''','  CpuFetchAddress()')
# Zero-page operands always address the local 2 KiB RAM, never an MMIO device.
# Keep bus values and both RMW writes while avoiding generic mapped-bus calls.
for match in list(re.finditer(r'(Op[0-9A-F]{2}: ; \$[0-9A-F]{2} \w+ (?:zpg|zpx|zpy)\n.*?)(?=Op[0-9A-F]{2}:|Done:)',s,re.S))[::-1]:
 body=[]
 for line in match[0].splitlines():
  if 'NesRead(Ea)' in line:
   body.append('  NesOpenBus = M(Ea)')
   line=line.replace('NesRead(Ea)','NesOpenBus')
  line=re.sub(r'NesWrite\(Ea, (\w+)\)',r'M(Ea) = \1 : NesOpenBus = \1',line)
  body.append(line)
 s=s[:match.start()]+'\n'.join(body)+'\n'+s[match.end():]
s=s.replace('  Ea = NesRead(Tmp) | (NesRead((Tmp + 1) & 255) << 8)',
            '  Lo = M(Tmp) : Hi = M((Tmp + 1) & 255) : NesOpenBus = Hi\n  Ea = Lo | (Hi << 8)')
# Exact batching of a side-effect-free JMP-to-self within the existing
# instruction-boundary cycle window. No guest cycles/instructions are dropped.
s=s.replace('Global NesInstructions.i','Global NesInstructions.i\nGlobal NesIdleEnabled.i=1, NesIdleExtra.i, NesIdleBatched.i')
s=s.replace('''Op4C: ; $4C JMP abs
  AccessPhase = 2
  CpuFetchAddress()
  PC = Ea''','''Op4C: ; $4C JMP abs
  AccessPhase = 2
  CpuFetchAddress()
  If Ea=((PC-3)&$FFFF)
  If NesIdleEnabled<>0 And Left>3 And NesStall=0 And (Ea<$1FFE Or Ea>=$8000)
    NesIdleExtra=NesDiv(Left-1,3)
    CpuCycles=CpuCycles+NesIdleExtra*3
    Left=Left-NesIdleExtra*3
    NesInstructions=NesInstructions+NesIdleExtra
    NesIdleBatched=NesIdleBatched+NesIdleExtra
  EndIf
  EndIf
  PC = Ea''')
# Branch displacement fetches use the same bounded ROM/RAM helper.
s=s.replace('Res = (NesRead(PC) ! 128) - 128\n    PC = (PC + 1 + Res) & $FFFF', 'Res = (CpuFetchByte() ! 128) - 128\n    PC = (PC + Res) & $FFFF')
# Status-poll superinstruction: an exact ROM LDA $2002 / AND #$40 / BEQ
# loop may repeat only inside both the cycle budget and proven status horizon.
# The current taken branch still owes its final two cycles. The last repeated
# status read is at CpuCycles+n*period-4 (or -5 across a page), so +4 is
# conservative for both. Counted loops stop while X is nonzero; the ordinary
# dispatcher executes the eventual terminating iteration.
s=s.replace('Global NesInstructions.i', 'Global NesInstructions.i\nGlobal PpuStatusDeadline.i, PpuStatusBits.i, NesPollPtr.i, NesPollCount.i, NesPollCycles.i')
body="""  If Res=-7
  If NesIdleEnabled<>0 And A=0 And (FZ&255)=0 And (PpuStatusBits&$40)=0 And Left>12 And PpuStatusDeadline>CpuCycles And PC>=$8000 And PC<=$FFF9
    NesPollPtr=PrgBias+PC
    If PeekA(NesPollPtr)=$AD And PeekA(NesPollPtr+1)=2 And PeekA(NesPollPtr+2)=$20 And PeekA(NesPollPtr+3)=$29 And PeekA(NesPollPtr+4)=$40 And PeekA(NesPollPtr+5)=$F0 And PeekA(NesPollPtr+6)=$F9
      NesPollCycles=9
      If (Base&$FF00)<>(PC&$FF00)
        NesPollCycles=10
      EndIf
      NesPollCount=NesDiv(Left-3,NesPollCycles)
      Tmp=NesDiv(PpuStatusDeadline-CpuCycles+4,NesPollCycles)
      If NesPollCount>Tmp
        NesPollCount=Tmp
      EndIf
      If NesPollCount>0
        Charge(NesPollCount*NesPollCycles)
        NesInstructions=NesInstructions+NesPollCount*3
        NesIdleBatched=NesIdleBatched+NesPollCount*3
        NesPollStatusDone()
        FN=0 : FZ=0 : NesOpenBus=$F9
      EndIf
    EndIf
  EndIf
  EndIf
"""
body+="""  If Res=-4
  If NesIdleEnabled<>0 And A=0 And (FZ&255)=0 And Left>9 And PC>=$8000 And PC<=$FFFC
    NesPollPtr=PrgBias+PC
    If PeekA(NesPollPtr)=$A5 And PeekA(NesPollPtr+2)=$F0 And PeekA(NesPollPtr+3)=$FC And M(PeekA(NesPollPtr+1))=0
      NesPollCycles=6
      If (Base&$FF00)<>(PC&$FF00)
        NesPollCycles=7
      EndIf
      NesPollCount=NesDiv(Left-3,NesPollCycles)
      Charge(NesPollCount*NesPollCycles)
      NesInstructions=NesInstructions+NesPollCount*2
      NesIdleBatched=NesIdleBatched+NesPollCount*2
      FN=0 : FZ=0 : NesOpenBus=$FC
    EndIf
  EndIf
  EndIf
"""
# Insert after taken/not-taken logic, before BEQ's ordinary final charge.
a=s.index('OpF0: ; $F0 BEQ rel'); b=s.index('OpF1:',a)
s=s[:a]+s[a:b].replace('  NextOp(2)',body+'  NextOp(2)')+s[b:]
body="""  If Res=-6
  If NesIdleEnabled<>0 And (FZ&255)<>0 And X>0 And Left>12 And PpuStatusDeadline>CpuCycles And PC>=$8000 And PC<=$FFFA
    NesPollPtr=PrgBias+PC
    If PeekA(NesPollPtr)=$AD And PeekA(NesPollPtr+1)=2 And PeekA(NesPollPtr+2)=$20 And PeekA(NesPollPtr+3)=$E8 And PeekA(NesPollPtr+4)=$D0 And PeekA(NesPollPtr+5)=$FA
      NesPollCycles=9
      If (Base&$FF00)<>(PC&$FF00)
        NesPollCycles=10
      EndIf
      NesPollCount=NesDiv(Left-3,NesPollCycles)
      Tmp=NesDiv(PpuStatusDeadline-CpuCycles+4,NesPollCycles)
      If NesPollCount>Tmp
        NesPollCount=Tmp
      EndIf
      If NesPollCount>255-X
        NesPollCount=255-X
      EndIf
      If NesPollCount>0
        Charge(NesPollCount*NesPollCycles)
        NesInstructions=NesInstructions+NesPollCount*3
        NesIdleBatched=NesIdleBatched+NesPollCount*3
        A=NesPollStatusDone()
        X=X+NesPollCount : FN=X : FZ=X : NesOpenBus=$FA
      EndIf
    EndIf
  EndIf
  EndIf
"""
a=s.index('OpD0: ; $D0 BNE rel'); b=s.index('OpD1:',a)
s=s[:a]+s[a:b].replace('  NextOp(2)',body+'  NextOp(2)')+s[b:]
# Countdown superinstruction: an exact ROM DEX/BNE or DEY/BNE loop onto itself (a timing delay, e.g.
# Pinbot's raster waits) runs further passes at once: each is 5 cycles (6 if the branch crosses a
# page) and 2 instructions, the counter falls by one, and no bus access happens. The taken branch
# just executed still owes its final two cycles (Left-3, as above); the batch stops one pass short
# of zero so the ordinary dispatcher executes the terminating DEX/BNE.
body="""  If Res=-3
  If NesIdleEnabled<>0 And (FZ&255)<>0 And Left>8 And PC>=$8000 And PC<=$FFFD
    NesPollPtr=PrgBias+PC
    If PeekA(NesPollPtr+1)=$D0 And PeekA(NesPollPtr+2)=$FD
      Tmp=PeekA(NesPollPtr)
      If Tmp=$CA Or Tmp=$88
        NesPollCycles=5
        If (Base&$FF00)<>(PC&$FF00)
          NesPollCycles=6
        EndIf
        NesPollCount=NesDiv(Left-3,NesPollCycles)
        If Tmp=$CA
          Ea=X
        Else
          Ea=Y
        EndIf
        If NesPollCount>((Ea-1)&255)
          NesPollCount=(Ea-1)&255
        EndIf
        If NesPollCount>0
          Charge(NesPollCount*NesPollCycles)
          NesInstructions=NesInstructions+NesPollCount*2
          NesIdleBatched=NesIdleBatched+NesPollCount*2
          Ea=(Ea-NesPollCount)&255
          If Tmp=$CA
            X=Ea
          Else
            Y=Ea
          EndIf
          FN=Ea : FZ=Ea : NesOpenBus=$FD
        EndIf
      EndIf
    EndIf
  EndIf
  EndIf
"""
a=s.index('OpD0: ; $D0 BNE rel'); b=s.index('OpD1:',a)
s=s[:a]+s[a:b].replace('  NextOp(2)',body+'  NextOp(2)')+s[b:]
# Forward declarations: bus includes the CPU memory and is defined after it.
s=s.replace('; NMOS 6502, documented opcodes. Flat 64 KiB writable guest memory.', '; NES 2A03, documented opcodes; mirrored RAM, cartridge ROM and NES bus.')
s=s.replace('; CpuRun executes whole instructions. No bus/dummy-cycle emulation.', '; CpuRun executes whole instructions; selected RMW writes, not full bus sequences.')
s=s.replace('; CpuCycles is maintained only with #CPU_TIMING = 1.', '; CpuCycles is always maintained; n is a CPU-cycle budget, not instruction count.')
s=s.replace('Global Dim M.a(65536)', 'Global Dim M.a(2048)')
s=s.replace('      ldr r1, =global_m\n      ldrb r2, [r1, r0]', '      ldr r1, =global_prgbias\n      ldr r1, [r1]\n      ldrb r2, [r1, r0]')
s=s.replace('EnableExplicit','''EnableExplicit
Declare.i NesRead(addr.i)
Declare NesWrite(addr.i, value.i)
Declare.i CpuFetchByte()
Declare CpuFetchAddress()
Declare.i NesPollStatusDone()''',1)
# Lean window accounting: inside CpuRun only Left (r11) moves per instruction.
# CpuCycles is derived as NesRunStart+Budget-Left wherever it is needed during
# a window (CpuNow in the bus), and stored once when the window ends. OAM DMA
# stalls are charged by the bus directly, so there is no per-instruction stall
# test. AccessPhase is stored only by opcodes whose operand can reach the NES
# bus devices (abs/abx/aby/ind/inx/iny); zero page, stack, immediate, implied
# and branch opcodes never touch MMIO, so their stores were dead.
s=s.replace('Global AccessPhase.i, NesStall.i, NesRunStart.i','Global AccessPhase.i, NesStall.i, NesRunStart.i, CpuInWindow.i',1)
s=s.replace('Macro Charge(c)\n  CpuCycles = CpuCycles + c\n  Left = Left - c\nEndMacro',
            'Macro Charge(c)\n  CpuCycles = CpuCycles + c\n  Left = Left - c\nEndMacro\nMacro Tick(c)\n  Left = Left - c\nEndMacro',1)
s=s.replace('If (Base & $FF00) <> (Ea & $FF00)\n      Charge(1)','If (Base & $FF00) <> (Ea & $FF00)\n      Tick(1)')
a=s.index('ProcedureRAM.i CpuRun(n.i)'); b=s.index('EndProcedure',s.index('\nDone:',a))
body=s[a:b]
old_next='  Charge(c)\n  NesInstructions = NesInstructions + 1\n  If NesStall\n    Charge(NesStall)\n    NesStall = 0\n  EndIf\n'
assert old_next in body
body=body.replace(old_next,'  Tick(c)\n  NesInstructions = NesInstructions + 1\n')
body=body.replace('Charge(','Tick(')
body=body.replace('  NesRunStart = CpuCycles\n',
  '  If NesStall\n    CpuCycles = CpuCycles + NesStall\n    NesStall = 0\n  EndIf\n  NesRunStart = CpuCycles\n  CpuInWindow = 1\n',1)
body=body.replace('\nDone:\n  ProcedureReturn CpuCycles - NesRunStart\n',
  '\nDone:\n  CpuCycles = NesRunStart + Budget - Left\n  CpuInWindow = 0\n  ProcedureReturn CpuCycles - NesRunStart\n')
body=body.replace(' And NesStall=0 And Ea=((PC-3)&$FFFF)',' And Ea=((PC-3)&$FFFF)')
body=body.replace('    CpuCycles=CpuCycles+NesIdleExtra*3\n','')
body=body.replace('PpuStatusDeadline>CpuCycles','PpuStatusDeadline>NesRunStart+Budget-Left')
body=body.replace('PpuStatusDeadline-CpuCycles+4','PpuStatusDeadline-(NesRunStart+Budget-Left)+4')
stray=[l for l in body.splitlines() if 'CpuCycles' in l and l.strip() not in (
  'CpuCycles = CpuCycles + NesStall','NesRunStart = CpuCycles','CpuCycles = NesRunStart + Budget - Left','ProcedureReturn CpuCycles - NesRunStart')]
assert not stray, stray
lean=[]; keep=True
for line in body.splitlines():
    m=re.match(r'Op[0-9A-F]{2}: ; \$[0-9A-F]{2} \w+ (\w+)',line)
    if m:
        keep=m[1] in ('abs','abx','aby','ind','inx','iny')
    elif line.startswith(('Done:','SlowFetch:','Illegal:')):
        keep=True
    if not keep and 'AccessPhase' in line:
        continue
    lean.append(line)
s=s[:a]+'\n'.join(lean)+'\n'+s[b:]
s=s.replace('; CpuCycles is always maintained; n is a CPU-cycle budget, not instruction count.',
            '; CpuCycles is exact outside CpuRun; inside it is NesRunStart+Budget-Left (CpuNow).')
# Inline operand fetches. CpuFetchByte/CpuFetchAddress cost a full call per
# operand; inside CpuRun the generator writes the same fast path inline with
# labels unique to each site, and keeps the slow path (code below $8000, or an
# address operand at $FFFF) on CpuFetchByteSlow/CpuFetchAddressSlow.
# Immediates: "X = NesRead(PC)" ... "PC = (PC + 1) & $FFFF" become an inline
# fetch into Opnd, which advances PC itself. The per-instruction NesInstructions
# count is dropped (only board checks read it; batching still adds to it).
s=s.replace('Global NesInstructions.i','Global NesInstructions.i, Opnd.i',1)
a=s.index('ProcedureRAM.i CpuRun(n.i)'); b=s.index('EndProcedure',s.index('\nDone:',a))
body=s[a:b]
assert body.count('  Tick(c)\n  NesInstructions = NesInstructions + 1\n')==1
body=body.replace('  Tick(c)\n  NesInstructions = NesInstructions + 1\n','  Tick(c)\n')
site=[0]
def fetch_byte(target):
    site[0]+=1; k=site[0]
    return f'''  ASM Uses PC
    mov r0, r8
    ldr r1, =$8000
    cmp r0, r1
    blo __cpu_ifs_{k}
    ldr r1, =global_prgbias
    ldr r1, [r1]
    ldrb r2, [r1, r0]
    adds r0, #1
    lsls r0, r0, #16
    lsrs r0, r0, #16
    mov r8, r0
    ldr r1, =global_nesopenbus
    str r2, [r1]
    b __cpu_ifd_{k}
__cpu_ifs_{k}:
    bl cpufetchbyteslow
    movs r2, r0
__cpu_ifd_{k}:
    ldr r1, =global_{target.lower()}
    str r2, [r1]
  EndASM
'''
def fetch_address():
    site[0]+=1; k=site[0]
    return f'''  ASM Uses PC
    mov r0, r8
    ldr r1, =$8000
    cmp r0, r1
    blo __cpu_ias_{k}
    ldr r1, =$ffff
    cmp r0, r1
    beq __cpu_ias_{k}
    ldr r1, =global_prgbias
    ldr r1, [r1]
    ldrb r2, [r1, r0]
    adds r0, #1
    ldrb r3, [r1, r0]
    ldr r1, =global_nesopenbus
    str r3, [r1]
    lsls r3, r3, #8
    orrs r2, r3
    ldr r1, =global_ea
    str r2, [r1]
    adds r0, #1
    lsls r0, r0, #16
    lsrs r0, r0, #16
    mov r8, r0
    b __cpu_iad_{k}
__cpu_ias_{k}:
    bl cpufetchaddressslow
__cpu_iad_{k}:
  EndASM
'''
out=[]; lines=body.split('\n'); i=0; inop=False; pending_pc=False
import re as _re
while i<len(lines):
    l=lines[i]
    if _re.match(r'Op[0-9A-F]{2}: ',l):
        inop=True; pending_pc=False
    elif _re.match(r'\w+:\s*$',l) or l.startswith('Done:'):
        inop=False
    if inop:
        m=_re.match(r'  Fetch\((\w+)\)$',l)
        if m:
            out.append(fetch_byte(m[1]).rstrip('\n')); i+=1; continue
        if l.strip()=='CpuFetchAddress()':
            out.append(fetch_address().rstrip('\n')); i+=1; continue
        if 'Res = (CpuFetchByte() ! 128) - 128' in l:
            ind=l[:len(l)-len(l.lstrip())]
            out.append(fetch_byte('Opnd').rstrip('\n'))
            out.append(ind+'Res = (Opnd ! 128) - 128'); i+=1; continue
        if 'NesRead(PC)' in l:
            assert not pending_pc, l
            out.append(fetch_byte('Opnd').rstrip('\n'))
            out.append(l.replace('NesRead(PC)','Opnd')); pending_pc=True; i+=1; continue
        if pending_pc and l.strip()=='PC = (PC + 1) & $FFFF':
            pending_pc=False; i+=1; continue
        if pending_pc:
            assert 'PC' not in l.replace('PC = ','').replace('NesPollPtr','') or l.strip().startswith(('NZ(','FC','FV','FN','FZ')), ('PC used before increment', l)
    out.append(l); i+=1
body='\n'.join(out)
assert 'CpuFetchByte()' not in body and 'CpuFetchAddress()' not in body
assert 'NesRead(PC)' not in body.split('Op00:')[1]
s=s[:a]+body+s[b:]
# Stores of A/X/Y (always 0..255) to work RAM are the common case: write the
# mirror directly, exactly as NesWrite's first branch does; devices, mapper
# registers and open bus still go through NesWrite.
for r in ('A','X','Y'):
    s=s.replace(f'  NesWrite(Ea, {r})\n',
                f'  If Ea<$2000\n    M(Ea&$7FF)={r} : NesOpenBus={r}\n  Else\n    NesWrite(Ea, {r})\n  EndIf\n')
# Operand reads from work RAM or cartridge ROM are read in place (what
# NesRead's fast path does, without the call); devices still use NesRead.
a=s.index('ProcedureRAM.i CpuRun(n.i)'); b=s.index('\nDone:',a)
body=[]
for line in s[a:b].split('\n'):
    if line.count('NesRead(Ea)')==1 and line.startswith('  ') and not line.startswith('   '):
        site[0]+=1; k=site[0]
        body+=['  ASM','    ldr r0, =global_ea','    ldr r0, [r0]','    lsrs r1, r0, #15',f'    beq __cpu_irl_{k}',
               '    ldr r1, =global_prgbias','    ldr r1, [r1]','    ldrb r2, [r1, r0]',f'    b __cpu_ird_{k}',
               f'__cpu_irl_{k}:','    lsrs r1, r0, #13',f'    bne __cpu_irs_{k}','    lsls r0, r0, #21','    lsrs r0, r0, #21',
               '    ldr r1, =global_m','    ldrb r2, [r1, r0]',f'    b __cpu_ird_{k}',
               f'__cpu_irs_{k}:','    bl nesread','    movs r2, r0',
               f'__cpu_ird_{k}:','    ldr r1, =global_nesopenbus','    str r2, [r1]','  EndASM',
               line.replace('NesRead(Ea)','NesOpenBus')]
    else:
        body.append(line)
s=s[:a]+'\n'.join(body)+s[b:]
# Interrupt-mask instructions end the host window when they unmask IRQs.
# CLI/PLP poll the old I flag, so the host executes one following instruction
# before taking a pending IRQ. RTI restores I before polling and has no delay.
s=s.replace('Global NesOpenBus.i','Global NesOpenBus.i\nGlobal CpuIrqDelay.i')
s=s.replace('  FI = 0\n  NextOp(2)\nOp59:', '  CpuIrqDelay=FI : FI = 0\n  Budget=Budget-Left : Left=0\n  NextOp(2)\nOp59:')
s=s.replace('  CpuSetStatus(Tmp)\n  NextOp(4)', '  CpuIrqDelay=FI : CpuSetStatus(Tmp)\n  Budget=Budget-Left : Left=0\n  NextOp(4)')
s=s.replace('  PC = Lo | (Hi << 8)\n  NextOp(6)\nOp41:', '  PC = Lo | (Hi << 8)\n  CpuIrqDelay=0 : Budget=Budget-Left : Left=0\n  NextOp(6)\nOp41:')

(root/'cpu2a03.pico').write_text(s)
print('Generated NES bus/cycle-budget core; decimal arithmetic disabled')
